def calculate_winner(lst, n):
    score_a = 0
    score_b = 0
    last_winner = None

    for outcome in lst:
        if outcome == 'A':
            if last_winner == 'A':
                score_a += 2
            else:
                score_a += 1
            last_winner = 'A'
        elif outcome == 'B':
            if last_winner == 'B':
                score_b += 2
            else:
                score_b += 1
            last_winner = 'B'
        elif outcome == 'T':
            last_winner = None

        if score_a >= n:
            return 'A'
        if score_b >= n:
            return 'B'

    return None
```

